import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';

void main() {
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return ScreenUtilInit(
      // 디자인 시안의 기준 크기 (일반적으로 iPhone 기준)
      designSize: const Size(375, 812), // iPhone X 기준
      // 최소 텍스트 크기 비율 (너무 작아지는 것 방지)
      minTextAdapt: true,
      // 화면 분할 시에도 적용
      splitScreenMode: true,
      builder: (context, child) {
        return MaterialApp(
          debugShowCheckedModeBanner: false,
          title: 'ScreenUtil Demo',
          theme: ThemeData(
            primarySwatch: Colors.blue,
            // 테마에서도 screenutil 사용 가능
            textTheme: TextTheme(
              bodyLarge: TextStyle(fontSize: 16.sp),
              bodyMedium: TextStyle(fontSize: 14.sp),
              titleLarge: TextStyle(fontSize: 20.sp),
            ),
          ),
          home: child,
        );
      },
      child: const HomeScreen(),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';

class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(
          '홈 화면',
          style: TextStyle(fontSize: 18.sp), // 폰트 크기
        ),
      ),
      body: Padding(
        padding: EdgeInsets.all(16.w), // 너비 기준 패딩
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 너비 기준 크기 (.w)
            Container(
              width: 200.w, // 디자인에서 200px → 화면 비율에 맞게 변환
              height: 100.h, // 높이 기준 크기 (.h)
              color: Colors.blue,
              child: Center(
                child: Text(
                  '200.w x 100.h',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 14.sp,
                  ),
                ),
              ),
            ),
            SizedBox(height: 20.h),

            // 반지름/정사각형용 (.r) - 작은 쪽 기준
            Container(
              width: 100.r,
              height: 100.r,
              decoration: BoxDecoration(
                color: Colors.green,
                borderRadius: BorderRadius.circular(16.r),
              ),
              child: Center(
                child: Text(
                  '100.r',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 14.sp,
                  ),
                ),
              ),
            ),
            SizedBox(height: 20.h),

            // 폰트 크기 (.sp)
            Text(
              '12.sp 텍스트',
              style: TextStyle(fontSize: 12.sp),
            ),
            Text(
              '16.sp 텍스트',
              style: TextStyle(fontSize: 16.sp),
            ),
            Text(
              '24.sp 텍스트',
              style: TextStyle(fontSize: 24.sp),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';

class ScreenInfoExample extends StatelessWidget {
  const ScreenInfoExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('화면 정보', style: TextStyle(fontSize: 18.sp))),
      body: Padding(
        padding: EdgeInsets.all(16.w),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _infoRow('화면 너비', '${ScreenUtil().screenWidth.toStringAsFixed(1)}px'),
            _infoRow('화면 높이', '${ScreenUtil().screenHeight.toStringAsFixed(1)}px'),
            _infoRow('상태바 높이', '${ScreenUtil().statusBarHeight.toStringAsFixed(1)}px'),
            _infoRow('하단 SafeArea', '${ScreenUtil().bottomBarHeight.toStringAsFixed(1)}px'),
            _infoRow('픽셀 비율', '${ScreenUtil().pixelRatio?.toStringAsFixed(2)}'),
            _infoRow('가로 모드', '${ScreenUtil().orientation == Orientation.landscape}'),
            _infoRow('너비 배율', '${ScreenUtil().scaleWidth.toStringAsFixed(3)}'),
            _infoRow('높이 배율', '${ScreenUtil().scaleHeight.toStringAsFixed(3)}'),
            SizedBox(height: 20.h),
            // 조건부 레이아웃
            Text(
              ScreenUtil().screenWidth > 600 ? '태블릿 레이아웃' : '폰 레이아웃',
              style: TextStyle(fontSize: 16.sp, fontWeight: FontWeight.bold),
            ),
          ],
        ),
      ),
    );
  }

  Widget _infoRow(String label, String value) {
    return Padding(
      padding: EdgeInsets.symmetric(vertical: 4.h),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(label, style: TextStyle(fontSize: 14.sp)),
          Text(value, style: TextStyle(fontSize: 14.sp, fontWeight: FontWeight.bold)),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';

class ProductListScreen extends StatelessWidget {
  const ProductListScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('상품 목록', style: TextStyle(fontSize: 18.sp)),
        actions: [
          IconButton(
            icon: Icon(Icons.search, size: 24.sp),
            onPressed: () {},
          ),
          IconButton(
            icon: Icon(Icons.shopping_cart, size: 24.sp),
            onPressed: () {},
          ),
        ],
      ),
      body: Column(
        children: [
          // 검색바
          Container(
            margin: EdgeInsets.all(16.w),
            padding: EdgeInsets.symmetric(horizontal: 16.w),
            height: 48.h,
            decoration: BoxDecoration(
              color: Colors.grey[100],
              borderRadius: BorderRadius.circular(8.r),
            ),
            child: Row(
              children: [
                Icon(Icons.search, color: Colors.grey, size: 20.sp),
                SizedBox(width: 8.w),
                Expanded(
                  child: TextField(
                    decoration: InputDecoration(
                      hintText: '상품 검색',
                      hintStyle: TextStyle(fontSize: 14.sp),
                      border: InputBorder.none,
                    ),
                    style: TextStyle(fontSize: 14.sp),
                  ),
                ),
              ],
            ),
          ),
          // 상품 그리드
          Expanded(
            child: GridView.builder(
              padding: EdgeInsets.symmetric(horizontal: 16.w),
              gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: 2,
                mainAxisSpacing: 16.h,
                crossAxisSpacing: 16.w,
                childAspectRatio: 0.7,
              ),
              itemCount: 10,
              itemBuilder: (context, index) => _ProductCard(index: index),
            ),
          ),
        ],
      ),
      bottomNavigationBar: Container(
        padding: EdgeInsets.all(16.w),
        decoration: BoxDecoration(
          color: Colors.white,
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.1),
              blurRadius: 10.r,
              offset: Offset(0, -5.h),
            ),
          ],
        ),
        child: SafeArea(
          child: SizedBox(
            height: 48.h,
            child: ElevatedButton(
              onPressed: () {},
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.blue,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(8.r),
                ),
              ),
              child: Text(
                '전체 상품 보기',
                style: TextStyle(fontSize: 16.sp, color: Colors.white),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _ProductCard extends StatelessWidget {
  final int index;

  const _ProductCard({required this.index});

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12.r),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.05),
            blurRadius: 10.r,
            offset: Offset(0, 4.h),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // 이미지 영역
          Expanded(
            flex: 3,
            child: Container(
              decoration: BoxDecoration(
                color: Colors.grey[200],
                borderRadius: BorderRadius.vertical(
                  top: Radius.circular(12.r),
                ),
              ),
              child: Center(
                child: Icon(
                  Icons.image,
                  size: 48.sp,
                  color: Colors.grey[400],
                ),
              ),
            ),
          ),
          // 정보 영역
          Expanded(
            flex: 2,
            child: Padding(
              padding: EdgeInsets.all(8.w),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    '상품 ${index + 1}',
                    style: TextStyle(
                      fontSize: 14.sp,
                      fontWeight: FontWeight.bold,
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                  SizedBox(height: 4.h),
                  Text(
                    '상품 설명이 들어갑니다',
                    style: TextStyle(
                      fontSize: 12.sp,
                      color: Colors.grey[600],
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                  const Spacer(),
                  Text(
                    '₩${(index + 1) * 10000}',
                    style: TextStyle(
                      fontSize: 16.sp,
                      fontWeight: FontWeight.bold,
                      color: Colors.blue,
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}
